SET TIME ZONE 'UTC';
CREATE TABLE datetime_dates(id INTEGER PRIMARY KEY, d DATE);
CREATE TABLE datetime_timestamps(id INTEGER PRIMARY KEY, t TIMESTAMP);
CREATE TABLE datetime_zones(id INTEGER PRIMARY KEY, z TIMESTAMPTZ);
INSERT INTO datetime_dates VALUES (1,'2020-01-01'),(2,'2020-01-01'),(3,'2020-01-02'),(4,'400000-01-01'),(5,'infinity'),(6,'-infinity'),(7,NULL);
INSERT INTO datetime_timestamps VALUES (1,'2020-01-01'),(2,'2020-01-01 12:00'),(3,'2020-01-02'),(4,'294000-01-01'),(5,'infinity'),(6,'-infinity'),(7,NULL);
INSERT INTO datetime_zones VALUES (1,'2020-01-01+00'),(2,'2019-12-31 15:00+00'),(3,'2020-01-02+00'),(4,'294000-01-01+00'),(5,'infinity'),(6,'-infinity'),(7,NULL);
PREPARE datetime_comparison(date,timestamp,timestamptz) AS SELECT $1=$2 AS date_timestamp,$1=$3 AS date_zone,$2>$1 AS reversed;

